_kr text, title_en text, aliases text[], year int, network text, genres text[], status text)) INSERT INTO public.dramas (title_kr, title_en, aliases, year, network, genres, status) SELECT title_kr, title_en, aliases, year, network, genres, status FROM incoming i WHERE NOT EXISTS (SELECT 1 FROM public.dramas d WHERE lower(d.title_en)=lower(i.title_en) OR d.title_kr=i.title_kr);